head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf05011";
scwin.rownum = 0;
scwin.result = null;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_datefmt_cal_intPayDd1();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf05011.onpageload' });
    }
};

/**
 * @method
 * @name init_datefmt_cal_intPayDd1
 * @description 초기화 — datefmt cal int Pay Dd1
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_intPayDd1 = function () { $c.date.checkCalendarFormat("cal_intPayDd1", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {

        const parentfm = ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] !== undefined ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] : undefined);
        const fm = (document.InputForm || { elements: [] });
        if (parentfm.int_pay_methd_cd[0].checked) {
            $c.util.getComponent("ipt_intPayMethdCd").setValue(parentfm.int_pay_methd_cd[0].value);
            $c.util.getComponent("ipt_intPayMethdNm").setValue("이표채");
        } else {
            if (parentfm.int_pay_methd_cd[1].checked) {
                $c.util.getComponent("ipt_intPayMethdCd").setValue(parentfm.int_pay_methd_cd[1].value);
                $c.util.getComponent("ipt_intPayMethdNm").setValue("복리채");
            } else {
                if (parentfm.int_pay_methd_cd[2].checked) {
                    $c.util.getComponent("ipt_intPayMethdCd").setValue(parentfm.int_pay_methd_cd[2].value);
                    $c.util.getComponent("ipt_intPayMethdNm").setValue("단리채");
                } else {
                    if (parentfm.int_pay_methd_cd[3].checked) {
                        $c.util.getComponent("ipt_intPayMethdCd").setValue(parentfm.int_pay_methd_cd[3].value);
                        $c.util.getComponent("ipt_intPayMethdNm").setValue("할인채");
                    } else {
                        if (parentfm.int_pay_methd_cd[4].checked) {
                            $c.util.getComponent("ipt_intPayMethdCd").setValue(parentfm.int_pay_methd_cd[4].value);
                            $c.util.getComponent("ipt_intPayMethdNm").setValue("복5단2");
                        } else {
                            if (parentfm.int_pay_methd_cd[5].checked) {
                                $c.util.getComponent("ipt_intPayMethdCd").setValue(parentfm.int_pay_methd_cd[5].value);
                                $c.util.getComponent("ipt_intPayMethdNm").setValue("기타");
                            }
                        }
                    }
                }
            }
        }
        $c.util.getComponent("ipt_isuDd").setValue(parentfm.isu_dd.value);
        $c.util.getComponent("ipt_redmptDd").setValue(parentfm.redmpt_dd.value);
        $c.util.getComponent("ipt_redmptDd2").setValue(parentfm.redmpt_dd.value);
        $c.util.getComponent("ipt_isuAmt").setValue(parentfm.isu_amt.value);
        if (parentfm.curr_tp_cd[0].checked) {
            $c.util.getComponent("ipt_currTpNm").setValue("원화");
        } else {
            if (parentfm.curr_tp_cd[1].checked) {
                $c.util.getComponent("ipt_currTpNm").setValue("달러");
            } else {
                if (parentfm.curr_tp_cd[2].checked) {
                    $c.util.getComponent("ipt_currTpNm").setValue("엔화");
                } else {
                    if (parentfm.curr_tp_cd[3].checked) {
                        $c.util.getComponent("ipt_currTpNm").setValue("유로화");
                    } else {
                        if (parentfm.curr_tp_cd[4].checked) {
                            $c.util.getComponent("ipt_currTpNm").setValue("위안화");
                        } else {
                            $c.util.getComponent("ipt_currTpNm").setValue("원화");
                        }
                    }
                }
            }
        }
        ($c.util.getComponent("txt_isuAmtCurr") && $c.util.getComponent("txt_isuAmtCurr").setValue) ? $c.util.getComponent("txt_isuAmtCurr").setValue($c.util.getComponent("ipt_currTpNm").getValue()) : (($c.util.getComponent("txt_isuAmtCurr") && $c.util.getComponent("txt_isuAmtCurr").setText) ? $c.util.getComponent("txt_isuAmtCurr").setText($c.util.getComponent("ipt_currTpNm").getValue()) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_isuAmtCurr"), void ($c.util.getComponent("ipt_currTpNm").getValue())));
        ($c.util.getComponent("txt_intPayAmt1Curr") && $c.util.getComponent("txt_intPayAmt1Curr").setValue) ? $c.util.getComponent("txt_intPayAmt1Curr").setValue($c.util.getComponent("ipt_currTpNm").getValue()) : (($c.util.getComponent("txt_intPayAmt1Curr") && $c.util.getComponent("txt_intPayAmt1Curr").setText) ? $c.util.getComponent("txt_intPayAmt1Curr").setText($c.util.getComponent("ipt_currTpNm").getValue()) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_intPayAmt1Curr"), void ($c.util.getComponent("ipt_currTpNm").getValue())));
        $c.util.getComponent("ipt_intPayUnitMms").setValue(parentfm.int_pay_unit_mms.value);
        $c.util.getComponent("ipt_coupnRt").setValue(parentfm.coupn_rt.value);
        $c.util.getComponent("ipt_redmptDd").setValue(parentfm.redmpt_dd.value);
        $c.util.getComponent("ipt_listAmt").setValue(parentfm.list_amt.value);
        $c.util.getComponent("cal_intPayDd1").setValue(parentfm.fst_int_pay_dd.value);
        scwin.makeInputFromParent();
        if (parentfm.princint_change.value === 'Y') {
            await $c.win.alert("이자산출에 필요한 정보가 변경되었습니다.\n\r금액을 다시 입력해주십시오.");
            await scwin.autoCalc();
        } else {
            if (parentfm.princint_save_yn.value === 'N') {
                await scwin.autoCalc();
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05011.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_autoCalc_onclick
 * @description btn_autoCalc 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_autoCalc_onclick = async function(e){
    try {
        await scwin.autoCalc()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05011.btn_autoCalc_onclick' }); }
};

/**
 * @method
 * @name btn_addRow_onclick
 * @description btn_addRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_addRow_onclick = function(e){
    try {
        scwin.addRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05011.btn_addRow_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delRow_onclick = async function(e){
    try {
        await scwin.delRow()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05011.btn_delRow_onclick' }); }
};

/**
 * @method
 * @name ipt_intPayAmt1_onpaste
 * @description ipt_intPayAmt1 onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_intPayAmt1_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05011.ipt_intPayAmt1_onpaste' }); }
};

/**
 * @method
 * @name btn_princintSendForm_onclick
 * @description btn_princintSendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_princintSendForm_onclick = async function(e){
    try {
        await scwin.princint_send_form()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05011.btn_princintSendForm_onclick' }); }
};

/**
 * @method
 * @name btn_princintSendClose_onclick
 * @description btn_princintSendClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_princintSendClose_onclick = function(e){
    try {
        scwin.princint_send_close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf05011.btn_princintSendClose_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_autoCalc
 * @description auto Calc 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_autoCalc = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — ../ajax/princ_int_cnt_data.jsp"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — ../ajax/princ_int_cnt_data.jsp", unresolved: "action:../ajax/princ_int_cnt_data.jsp" };
};

/**
 * @method
 * @name tx_fn_autoCalc_1
 * @description auto Calc 1 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_autoCalc_1 = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — ../ajax/princ_int_data.jsp"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — ../ajax/princ_int_data.jsp", unresolved: "action:../ajax/princ_int_data.jsp" };
};

/**
 * @method
 * @name NumberCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.NumberCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^0-9]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name cal_offMask
 * @description cal off Mask 처리
 * @returns {void}
 * @hidden N
 */
scwin.cal_offMask = function () { /* 등가 no-op — to-be 필드 마스크 미사용 */ };

/**
 * @method
 * @name chkDate
 * @description chk Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkDate = function () { /* 등가 no-op — 날짜 형식은 inputCalendar·제출 검증 몫 */ };

/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function () {
    const fm = (document.InputForm || { elements: [] });
    const rowPlus = $c.util.getComponent("tbl_princint");
    let tr;
    let th;
    let td;
    const newRowNum = scwin.rownum + 1;
    const curr_tp_nm = $c.util.getComponent("ipt_currTpNm").getValue();
    const $tblNonEq = $('#tbl_princint');
    const $tr = $("<tr></tr>");
    const $td1 = $("<td>" + newRowNum + "차</td>").addClass('first txc');
    const $td2 = $("<td><div style=\"display:flex; align-items:center;\"><input type=\"text\" id=\"int_pay_dd" + newRowNum + "\" name=\"int_pay_dd" + newRowNum + "\" value=\"\" maxlength=8 class=\"txt input-calendar\" style=\"height: 24px;\" title=\"날짜입력\" onBlur=\"Chk_Date2( this,'이자지급일 " + newRowNum + "차' )\" onfocus=\"cal_offMask('document.InputForm.int_pay_dd" + newRowNum + "')\" onkeyup=\"chkDate('document.InputForm.int_pay_dd" + newRowNum + "')\" /></div></td>");
    const $td3 = $("<td><input type=\"text\" name=\"int_pay_amt" + newRowNum + "\" value=\"\" onFocus=\"Del_MoneyComma(this);select();\" onBlur =\"Add_MoneyComma(this)\" class=\"txt mlong\" maxlength=\"18\"  onkeypress=\"NumberCheck(this)\" style=\"text-align: right;IME-MODE:disabled;\" onpaste=\"return false;\" /><span id=\"int_pay_amt" + newRowNum + "_curr\" class=\"kmoney\"></span> " + curr_tp_nm + "&nbsp;&nbsp;</td>");
    $tr.append($td1);
    $tr.append($td2);
    $tr.append($td3);
    $tblNonEq.append($tr);
    scwin.rownum++;
    $("#int_pay_dd" + newRowNum).datepicker(myDateOpts);
};

/**
 * @method
 * @name delRow
 * @description del Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delRow = async function () {
    const rowPlus = $c.util.getComponent("tbl_princint");
    if (scwin.rownum > 0) {
        const no = rowPlus.rows.length - 1;
        rowPlus.deleteRow(no);
        scwin.rownum--;
    } else {
        if (scwin.rownum < 1) {
            await $c.win.alert("삭제 할 행이 없습니다.");
        }
    }
};

/**
 * @method
 * @name makeInputFromParent
 * @description make Input From Parent 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeInputFromParent = function () {

    const parentfm = ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] !== undefined ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] : undefined);
    const fm = (document.InputForm || { elements: [] });
    if (parentfm.princint_count.value === '') {
        scwin.rownum = 0;
    } else {
        scwin.rownum = parseInt(parentfm.princint_count.value);
    }
    const rowPlus = $c.util.getComponent("tbl_princint");
    let tr;
    let td;
    const curr_tp_nm = $c.util.getComponent("ipt_currTpNm").getValue();
    let temprow = 0;
    if (scwin.rownum > 0) {
        temprow = scwin.rownum;
        $("#tbl_princint tr").remove();
        scwin.rownum = 0;
        for (let i = 1; i < temprow + 1; i++) {
            scwin.addRow();
            if (temprow === 1) {
                $c.util.getComponent("fm.int_pay_dd" + i).setValue(parentfm.int_pay_dd.value);
                $c.util.getComponent("fm.int_pay_amt" + i).setValue(parentfm.int_pay_amt.value);
            } else {
                if (temprow > 1) {
                    $c.util.getComponent("fm.int_pay_dd" + i).setValue(eval("parentfm.int_pay_dd[" + (i - 1) + "].value"));
                    $c.util.getComponent("fm.int_pay_amt" + i).setValue(eval("parentfm.int_pay_amt[" + (i - 1) + "].value"));
                }
            }
        }
    } else {
        scwin.rownum = 1;
    }
    if (parentfm.int_mmend_tp_cd[0].checked) {
        $c.util.getComponent("ipt_intMmendTpCd").setValue("1");
    } else {
        if (parentfm.int_mmend_tp_cd[1].checked) {
            $c.util.getComponent("ipt_intMmendTpCd").setValue("2");
        }
    }
    if (parentfm.bnd_int_pay_dd_bas_tp_cd[0].checked) {
        $c.util.getComponent("ipt_bndIntPayDdBasTpCd").setValue("1");
    } else {
        if (parentfm.bnd_int_pay_dd_bas_tp_cd[1].checked) {
            $c.util.getComponent("ipt_bndIntPayDdBasTpCd").setValue("2");
        }
    }
};

/**
 * @method
 * @name isYunMonth
 * @description is Yun Month 처리
 * @param {*} strYear strYear
 * @returns {void}
 * @hidden N
 */
scwin.isYunMonth = function (strYear) {
    nYear = parseInt(strYear);
    if ((nYear % 4) === 0) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name getFstIntPayDd
 * @description get Fst Int Pay Dd 처리
 * @param {*} i_dt i_dt
 * @param {*} r_dt r_dt
 * @param {Number} i i
 * @param {Number} cnt cnt
 * @returns {void}
 * @hidden N
 */
scwin.getFstIntPayDd = function (i_dt, r_dt, i, cnt) {

    const parentfm = ((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] !== undefined ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {}))["SendForm"] : undefined);
    let sendUrl = "";
    if (parentfm.bnd_int_pay_dd_bas_tp_cd[0].checked) {
        sendUrl = "/common/common.do?method=getFstIntPayDd&bnd_int_pay_dd_bas_tp_cd=1&isu_dd=" + i_dt + "&redmpt_dd=" + r_dt + "&int_pay_unit_mms=" + cnt + "&icount=" + i;
    } else {
        sendUrl = "/common/common.do?method=getFstIntPayDd&bnd_int_pay_dd_bas_tp_cd=2&isu_dd=" + i_dt + "&redmpt_dd=" + r_dt + "&int_pay_unit_mms=" + cnt + "&icount=" + i;
    }
    $.ajax({ type: "POST", async: false, url: sendUrl, data: $("#SendForm").serialize(), success: function(data) {
                scwin.result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                $c.util.getComponent("document.InputForm.int_pay_dd" + i).setValue(scwin.result.sendResult.substring(0, 4) + "-" + scwin.result.sendResult.substring(4, 6) + "-" + scwin.result.sendResult.substring(6, 8));
            }, error: async function(request, status, error) {
                await $c.win.alert("현재 이자지급일을 조회 할 수 없습니다. 관리자에게 문의하십시오.");
                return;
            }, complete: function() {

            } });
};

/**
 * @method
 * @name princint_send_form
 * @description princint send form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
