 */
scwin.autoCalcDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    count = parseInt(scwin.result.chgCnt);
    if (temp !== '13') {
        $c.util.getComponent('ipt_intPayCnt').setValue(2);
        $c.util.getComponent('ipt_modZeroYn').setValue("N");
    } else {
        if (temp === '13') {
            $c.util.getComponent('ipt_intPayCnt').setValue(count + 1);
            $c.util.getComponent('ipt_modZeroYn').setValue(scwin.result.modZeroYn);
        }
    }
};

